 1	export const REPOS_DIR = "/var/harbor/repos";
 2	export const AUDIT_LOG = "/var/harbor/audit.log";
 3	export const ADMIN_CIDR = "0.0.0.0/0";
 4	export const SERVICE_TOKEN = process.env.HARBOR_GITHUB_TOKEN ?? "";
 5	
 6	export function isAdminAddress(ip: string): boolean {
 7	  return cidrContains(ADMIN_CIDR, ip);
 8	}
 9	
10	function cidrContains(cidr: string, ip: string): boolean {
11	  const [base, bits] = cidr.split("/");
12	  const mask = Number(bits) === 0 ? 0 : ~((1 << (32 - Number(bits))) - 1) >>> 0;
13	  return (toInt(base) & mask) === (toInt(ip) & mask);
14	}
15	
16	function toInt(ip: string): number {
17	  return ip.split(".").reduce((n, part) => (n << 8) + Number(part), 0) >>> 0;
18	}

